import csv, re
from datetime import datetime
from collections import OrderedDict

def parse_date(s):
    s=s.strip()
    for f in ('%Y-%m-%d','%m/%d/%Y','%d %b %Y'):
        try: return datetime.strptime(s,f)
        except ValueError: pass
    raise ValueError(s)

def parse_cents(s):
    s=s.strip()
    s=re.sub(r'^USD\s*','',s)
    s=re.sub(r'\s*USD$','',s)
    s=s.replace('$','').replace(',','')
    # integer cents
    return int(round(float(s)*100))

cat_map={
 'taxi':'Travel','uber':'Travel','flight':'Travel',
 'hotel':'Lodging','airbnb':'Lodging',
 'lunch':'Meals','dinner':'Meals','coffee':'Meals',
 'saas':'Software','software':'Software','license':'Software',
 'books':'Learning','course':'Learning',
}

rows=list(csv.DictReader(open('expenses.csv')))
seen=OrderedDict()
for r in rows:
    rid=r['id'].strip()
    if rid in seen:
        print("dup id", rid, "identical:", seen[rid]==r)
        continue
    seen[rid]=r

items=[]
for rid,r in seen.items():
    d=parse_date(r['date'])
    if d.year!=2026 or d.month!=10: continue
    if r['status'].strip().lower()=='void': continue
    cat=cat_map[r['category'].strip().lower()]
    c=parse_cents(r['amount'])
    items.append((int(rid),cat,c))

agg={}
for rid,cat,c in items:
    a=agg.setdefault(cat,[0,0])
    a[0]+=1; a[1]+=c

total=sum(c for _,_,c in items)
print("items",len(items),"total cents",total, f"${total/100:,.2f}")
for cat,(n,c) in sorted(agg.items(), key=lambda kv:-kv[1][1]):
    print(cat,n,f"${c/100:,.2f}")
print("sum check", sum(v[1] for v in agg.values())==total)
print("flags")
for rid,cat,c in sorted(items):
    if c>50000: print(rid,cat,f"${c/100:,.2f}")
EOF", "description": "Compute October expense report values"}

